"""Validation-only complete-record replay; never changes canonical comparators."""
import copy
import hashlib
import json
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'tools'))
import conformance as c


def strict_json(text):
    def unique(pairs):
        result={}
        for k,v in pairs:
            if k in result:raise ValueError('Duplicate JSON field')
            result[k]=v
        return result
    return json.loads(text,object_pairs_hook=unique,parse_constant=lambda value:(_ for _ in ()).throw(ValueError('Nonfinite JSON')))


def strict(text,cases):
    lines=text.splitlines()
    if len(lines)!=len(cases) or any(not line.strip() for line in lines):raise ValueError('Complete framing differs')
    rows=[strict_json(line) for line in lines]
    for row,case in zip(rows,cases):
        keys={'id','width','height','pixels'}
        if case.get('export_qoi'):keys.add('qoi')
        if 'palette' in case:keys.update(('palette','palette_count'))
        if 'alpha_border' in case:keys.add('alpha_border')
        if type(row) is not dict or row.keys()!=keys:raise ValueError('Exact schema differs')
        if type(row['id']) is not str or any(type(row[k]) is not int for k in ('width','height')):raise ValueError('Metadata type differs')
        if 'palette_count' in row and type(row['palette_count']) is not int:raise ValueError('Palette type differs')
        for field in ('pixels','qoi','palette','alpha_border'):
            if field in row and (type(row[field]) is not list or any(type(v) is not int for v in row[field])):raise ValueError('Array type differs')
    # Retain the canonical domain checks unchanged, then compare entire records.
    c.parse_output(text,cases)
    return rows


def main():
    build=ROOT/'.build';cases=json.loads((build/'scenarios.json').read_text());report=json.loads((build/'conformance.json').read_text())
    if report.get('passed') is not True:raise ValueError('Canonical run did not pass')
    reference=strict((build/'reference.jsonl').read_text(),cases)
    counts=dict(scenarios=len(reference),words=sum(len(r['pixels']) for r in reference),qoi_bytes=sum(len(r.get('qoi',[])) for r in reference),palette_words=sum(len(r.get('palette',[])) for r in reference))
    if counts!=dict(scenarios=261,words=40101,qoi_bytes=333,palette_words=23):raise ValueError('Canonical coverage changed')
    # A changed optional field, boolean integer, duplicate field, blank line,
    # extra field, missing row or row order must fail this validator.
    text=(build/'reference.jsonl').read_text();bad=[]
    rows=copy.deepcopy(reference);rows[0]['width']=True;bad.append('\n'.join(map(json.dumps,rows)))
    rows=copy.deepcopy(reference);rows[0]['extra']=1;bad.append('\n'.join(map(json.dumps,rows)))
    rows=reference[1:]+reference[:1];bad.append('\n'.join(map(json.dumps,rows)))
    bad += [text+'\n', '\n'.join(text.splitlines()[1:]),text.replace('"width":','"width":1,"width":',1)]
    for wrong in bad:
        try:strict(wrong,cases)
        except (ValueError,KeyError):pass
        else:raise ValueError('Strict framing negative control accepted')
    lanes={}
    for lane in ('cpu-1','cpu-2','javascript'):
        path=build/(lane+'.jsonl');actual=strict(path.read_text(),cases)
        if reference!=actual:raise ValueError('Complete native/candidate records differ: '+lane)
        lanes[lane]=dict(passed=True,sha256=hashlib.sha256(path.read_bytes()).hexdigest(),**counts)
    artifacts={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [Path(__file__),build/'reference.jsonl',build/'scenarios.json',build/'conformance.json']}
    result=dict(passed=True,scope='validation-only strict complete-record replay',sources=c.source_gate(),artifacts=artifacts,lanes=lanes,negative_controls=len(bad))
    (build/'reconstruction-validation/strict-replay.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(dict(passed=True,lanes=lanes)))


if __name__=='__main__':main()

