def main():
    build=ROOT/'.build';cases=json.loads((build/'scenarios.json').read_text());report=json.loads((build/'conformance.json').read_text())
    if report.get('passed') is not True:raise ValueError('Canonical run did not pass')
    reference=strict((build/'reference.jsonl').read_text(),cases)
    counts=dict(scenarios=len(reference),words=sum(len(r['pixels']) for r in reference),qoi_bytes=sum(len(r.get('qoi',[])) for r in reference),palette_words=sum(len(r.get('palette',[])) for r in reference))
